-- migrate-v6: reset data lama dan muat daftar aset 2026 (697 unit).
-- Jalankan: node scripts/run-sql.mjs db/migrate-v6-aset-2026.sql
-- PERINGATAN: menghapus SEMUA aset, riwayat peminjaman, dan gambar jenis lama.
begin;
truncate table borrowings, asset_images, assets restart identity cascade;

-- kategori dari kolom "Jenis BMN" (dibuat bila belum ada)


update assets set qr_code = 'QR' || lpad(id::text, 6, '0'), qr_generated_at = now() where qr_code is null;
commit;
